				failure = KernelRuntime.closeResource(afterClose, failure);
				afterClose = null;
				failure = KernelRuntime.closeResource(secondLease, failure);
				secondLease = null;
				failure = KernelRuntime.closeResource(firstLease, failure);
				firstLease = null;
				firstContext = null;
