	private static final class SharedMemory {
		private final LmdbQueryMemoryManager.QueryLedger ledger;
		private final KernelRuntime.AggregateMemory memory;
		private long bytes;

		SharedMemory(LmdbQueryMemoryManager.QueryLedger ledger, long initial) {
			this.ledger = ledger;
			memory = KernelRuntime.AggregateMemory.forLedger(ledger);
			reserve(initial);
		}

		private SharedMemory(LmdbQueryMemoryManager.QueryLedger ledger) {
			this.ledger = ledger;
			memory = KernelRuntime.AggregateMemory.forLedger(ledger);
		}

		static SharedMemory tryOpen(LmdbQueryMemoryManager.QueryLedger ledger, long initial) {
			SharedMemory memory = new SharedMemory(ledger);
			if (!memory.memory.tryReserve(initial)) {
				memory.memory.close();
				return null;
			}
			memory.bytes = initial;
			return memory;
		}

		synchronized void reserve(long amount) {
			if (!tryReserve(amount)) {
				throw new AdmissionRefused(amount);
			}
		}

		synchronized boolean tryReserve(long amount) {
			long next = Math.addExact(bytes, amount);
			if (!memory.tryReserve(amount)) {
				return false;
			}
			bytes = next;
			return true;
		}

		synchronized long bytes() {
			return bytes;
		}

		synchronized void release(long amount) {
			if (amount < 0L || amount > bytes) {
				throw new IllegalStateException("Unbalanced decoded payload ownership");
			}
			bytes -= amount;
			memory.release(amount);
			if (bytes == 0L) {
				memory.close();
			}
		}
	}

	private static final class Allowance implements NativeSpillValueCodec.DecodeBudget {
		private long remaining;

		Allowance(long bytes) {
			remaining = bytes;
		}

		@Override
		public void beforeAllocation(long bytes) throws IOException {
			if (bytes < 0L || bytes > remaining) {
				throw new IOException("Runtime value exceeds its admitted encoded footprint");
			}
			remaining -= bytes;
		}
	}

